import{_ as e,o as t,c as o,Q as n}from"./chunks/framework.b67c47e6.js";const a="/assets/company-settings.3868bd6d.svg",f=JSON.parse('{"title":"Management - Company Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/management/index.md","filePath":"guide/management/index.md","lastUpdated":1790354386000}'),s={name:"guide/management/index.md"},r=n('<h1 id="management-company-settings" tabindex="-1">Management - Company Settings <a class="header-anchor" href="#management-company-settings" aria-label="Permalink to &quot;Management - Company Settings&quot;">​</a></h1><p>Open <strong>Company settings</strong> from the <strong>Settings</strong> section of the left menu, in company-wide mode. Company managers and admins can open it. Editing the company info, the interface settings, the backups and the work calendar is reserved for admins.</p><h2 id="main-settings" tabindex="-1">Main settings <a class="header-anchor" href="#main-settings" aria-label="Permalink to &quot;Main settings&quot;">​</a></h2><h3 id="company-info" tabindex="-1">Company info <a class="header-anchor" href="#company-info" aria-label="Permalink to &quot;Company info&quot;">​</a></h3><p>Company info such as name, address and emails is shown on reports, mails and other templates. Company notifications are sent to the &quot;Contact email&quot;. Admins change it with <strong>EDIT INFO</strong> on the company card.</p><h3 id="interface-settings" tabindex="-1">Interface settings <a class="header-anchor" href="#interface-settings" aria-label="Permalink to &quot;Interface settings&quot;">​</a></h3><p>Admins open these with <strong>SETTINGS</strong> on the company card. The dialog has two blocks, <em>Interface/Viewer Settings</em> and <em>Company Workflow Settings</em>.</p><p><img src="'+a+'" alt="The company Settings dialog"></p><ol><li><em>Interface/Viewer Settings</em>.</li><li>A text field that takes <code>{property}</code> names, with its <strong>Insert property</strong> button.</li><li><em>Company Workflow Settings</em>.</li><li><strong>Kitted parts</strong>. See <a href="/guide/logistics/#kitted-parts">Kitted Parts</a>.</li></ol><p><em>Interface/Viewer Settings</em></p><ul><li><strong>Use corporate color in the interface</strong>: the same switch as in the Styles card (see <a href="#styles">Styles</a>).</li><li><strong>Show QR button</strong>: Show a button in the panel viewer that gives the user a QR for the panel.</li><li><strong>Show RFID button</strong>: Show a button in the panel viewer that gives the option to register RFID tags.</li><li>Hiding parts in the 3D viewer is no longer a company setting. It is a <strong>custom part class</strong> in your parsing setup: give the class the rules that recognise those parts and turn on <em>Hide in the 3D viewer</em>. That way each setup decides for itself, instead of one switch deciding for the whole company. See: <a href="/guide/management/ifcps/#custom-part-classes">Custom part classes</a></li><li><strong>Show project number in the project selector</strong>: Adds the project number above the project name in the project selector, and next to the project name in the views that list projects from several projects at once. The number is left out when the project name or the superproject already starts with it. With this on, the selector also gets a search box that matches name, number and superproject.</li><li><strong>Avoid native camera in viewer</strong>: pictures are taken inside the app instead of opening the device&#39;s camera. Turn it on only if your tablets are managed by a policy that blocks the camera app, which makes the camera button open the photo gallery.</li><li><strong>Language</strong>: the default language for the app. Users can change the language if they are allowed by the admin (see the Users table).</li><li><strong>Custom Viewer Header</strong>, <strong>Custom List Hint</strong> and <strong>Custom Constructibles Table Column</strong>: replace the panel header in the viewer, the second line of each row in the viewer list, and add a column to the constructibles table, with a text you write using placeholders. See: <a href="/guide/properties/">Properties in Texts</a></li><li><strong>Zones from 10 are subzones</strong>: in the 3D viewer, zones from 10 upwards are shown together with their main zone (zone 10 with zone 1, zone -25 with zone -2, and so on).</li></ul><p><em>Company Workflow Settings</em></p><ul><li><strong>Production list based on dates</strong>: production works from a list per day instead of per project.</li><li><strong>Forced time registration in viewer</strong>: production users have to start the checklist of a panel before they can work on it in the viewer.</li><li><strong>Launch analysis automatically</strong>: on by default. New designs are analysed as soon as their files arrive.</li><li><strong>Best effort panel orientation</strong>: off by default. When the parsing setup cannot place a panel, its orientation is worked out from the geometry. The front face may come out on the wrong side; machine files never use it.</li><li><strong>Kitted parts</strong>: <em>Off</em> (no kit tracking), <em>Manual</em> (the operator marks a constructible kitted from the logistics viewer) or <em>Automatic</em>, marked <em>Recommended</em> (a constructible is kitted when all its parts are ready).</li><li><strong>Part reference</strong>: how part references are set: <em>From the parsing setup</em>, <em>Automatic reference</em>, or <em>From the parsing setup, automatic when missing</em> (the default). An automatic reference is given by the part&#39;s shape: two parts with the same shape get the same reference, even when one of them was modelled turned end for end or upside down, and a mirrored part gets a different one. This holds for projects created from 26 September 2026 on; older projects keep the references they already have.</li></ul><h2 id="licenses" tabindex="-1">Licenses <a class="header-anchor" href="#licenses" aria-label="Permalink to &quot;Licenses&quot;">​</a></h2><p>Gives an overview of the licensing: the maximum number of licenses per product, with how many are in use where it applies (for example <code>3/5</code>), and which modules the company has.</p><h2 id="styles" tabindex="-1">Styles <a class="header-anchor" href="#styles" aria-label="Permalink to &quot;Styles&quot;">​</a></h2><p>Corporate color and logos can be changed. They are also used in PDF generation. Sticker banner is a wide logo to be used in some of the sticker presets (like panel QR stickers).</p><p>Once you pick a corporate color it is used across the interface (buttons, links, scrollbars) and in PDF generation. If you prefer the standard produuz.it orange in the interface, untick &quot;Use corporate color&quot; next to the color picker — the color is kept and still used in PDFs.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>Projects are managed in <strong>Projects Settings</strong>, in the <strong>Settings</strong> section of the left menu. Projects are fabrication sets; we recommend no more than 100 designs and 500 panels per project for performance reasons. The more panels in a project, the slower the interface gets.</p><p>Some large projects do not fit in those numbers, so we introduced the &quot;superproject&quot; parameter, so you can group several projects under the same key name. For example, you may have a big project with 10 buildings, and you may want to split it into 10 projects that belong to the same superproject.</p><p>Projects can be &quot;archived&quot; 🗃. Archived projects are hidden from the user and only visible in the archive. To keep a full copy of archived projects, include them in a <a href="/guide/management/backup/">company backup</a>.</p><p>Each project can have an <strong>engineering contact</strong> — the person to reach with questions about it, typically the responsible engineer. In the project form (and in Project Settings), pick an existing contact or create a new one on the spot. Once set, it is shown to production staff in the issue detail panel (see <a href="#contacts">Contacts</a>).</p><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><p>The <strong>User accounts</strong> table lists everyone in the company: the people who log in and the production employees who do not. Its columns are Alias, Username, Login, Email, Role, Production station, Prod. Employees, Licenses and Actions.</p><h3 id="user-form" tabindex="-1">User form <a class="header-anchor" href="#user-form" aria-label="Permalink to &quot;User form&quot;">​</a></h3><ul><li><strong>Alias</strong>: required. How this person is identified in the factory; shown on the checklist and in the reports.</li><li><strong>Username</strong>: used to log in, and unique across produuz.it. Leave it empty for someone who does not log in.</li><li>🌐 <strong>Multilanguage</strong>: the user can change the language of the interface.</li><li>👁 <strong>Hide panel queue</strong>: if checked, the user sees only the designs mode in the viewer, not the panel list.</li><li>🔃 <strong>Can change station</strong>: the user can switch to another station.</li><li>🔄 <strong>Can change production line</strong>: the user can switch to another production line.</li><li>🌴 <strong>Has own holidays</strong>: if checked, the user does not get the company holidays. Only the user&#39;s own holidays are used.</li><li>🔨 <strong>Has own worktime</strong>: if checked, the user&#39;s own entries have priority over the company entries. This means that if you set a worktime with start and end date, all days outside this range will take company worktime.</li></ul><div class="info custom-block"><p class="custom-block-title">Work Calendar</p><p>More about holidays and worktime in <a href="#work-calendar">Work Calendar</a></p></div><h2 id="contacts" tabindex="-1">Contacts <a class="header-anchor" href="#contacts" aria-label="Permalink to &quot;Contacts&quot;">​</a></h2><p>Contacts are people to reach about a project, such as the responsible engineer. A contact has a name, phone and email, and is <strong>not</strong> a system user.</p><p>Manage them in the <strong>Contacts</strong> table, below User accounts. You can also add a contact directly from the project form when assigning one.</p><p>A project can have an <strong>engineering contact</strong> (set in the project form or in Project Settings). When it does, that contact is shown to production staff in the issue detail panel, so they know who to reach with questions about an issue.</p><h2 id="api-accounts" tabindex="-1">API accounts <a class="header-anchor" href="#api-accounts" aria-label="Permalink to &quot;API accounts&quot;">​</a></h2><p>The <strong>API Accounts</strong> table, below Contacts, holds the accounts that external systems use to connect to produuz.it. See <a href="/guide/api/#api-accounts">API accounts</a>.</p><h2 id="machines" tabindex="-1">Machines <a class="header-anchor" href="#machines" aria-label="Permalink to &quot;Machines&quot;">​</a></h2><p>Machines represent CNC equipment or automated stations in your production lines. Each machine setup has a model (e.g., Mobi One) and a configuration that defines how machine files are generated.</p><p>Machine setups live in <strong>Production Settings &gt; Machine Settings</strong> in the left menu. A setup is linked to a station, or to a whole production line, in <strong>Production Settings &gt; Production lines</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For details on configuring production lines, stations, and machines, see the <a href="/guide/management/production_lines/">Production Lines</a> reference page.</p></div><h2 id="work-calendar" tabindex="-1">Work Calendar <a class="header-anchor" href="#work-calendar" aria-label="Permalink to &quot;Work Calendar&quot;">​</a></h2><p>The work calendar controls how production time is calculated across the system. It defines working hours and holidays at both the company and user level.</p><p>The <strong>Work calendar</strong> card is at the bottom of Company settings and is visible to admins only.</p><ul><li><strong>Company holidays</strong>: Default holidays that apply to all users (pick the non working days in the calendar).</li><li><strong>Company worktime</strong>: Default working hours and breaks (start/end times per weekday), added with <strong>Add entry</strong>.</li><li><strong>User-level overrides</strong>: Individual users can have their own holidays and worktime entries (configured in the Users form with the &quot;Has own holidays&quot; and &quot;Has own worktime&quot; checkboxes).</li></ul>',42),i=[r];function c(h,l,d,p,m,u){return t(),o("div",null,i)}const w=e(s,[["render",c]]);export{f as __pageData,w as default};
